properties.property:
[
  {
    "text": "Hello, planeswalker {var=player_name}.",
    "options": [
      {
        "name": "Why am I here?",
        "condition": [
          {
            "checkQuestFlag": "mainQuest",
            "not": true
          },
          {
            "checkCharacterFlag": "noQuest",
            "not": true
          }
        ],
        "text": "Easy - breathe. The stasis takes time to shed. You are awake, Guardian... after three thousand years, you are awake. This cave was your prison. And this plane is what remains of your realm.",
        "options": [
          {
            "name": "(Continue)",
            "text": "You remember the Night of Chains? Five walkers. Five Seals, cut from your own stolen power. A realm left to grey and die while you slept beneath it. They have returned - their castles stand at the compass points, and their colors crawl across the ash, claiming what was never theirs.",
            "options": [
              {
                "name": "(Continue)",
                "text": "I am the last Warden. My order kept your vigil for a hundred generations, and died waiting for this day. So rebuild, Guardian. Raise Orazca. Gather the survivors. And when you are strong - take back the five Seals from the five thrones.",
                "options": [
                  {
                    "name": "(Continue)",
                    "text": "Take this rune. If you ever need to get back to me, use it - it will carry you home to this fire, from anywhere in the realm. The realm waited three thousand years for you, Guardian; do not make it wait again.",
                    "action": [
                      {
                        "grantRewards": [
                          {
                            "type": "item",
                            "count": 1,
                            "itemName": "Colorless rune"
                          }
                        ]
                      }
                    ],
                    "options": [
                      {
                        "name": "Thank you.",
                        "text": "I will reopen the portal now. On the other side lie the ash-barrens of the Forsaken Realms - your realm, Guardian, grey as it is. Bring the color back.",
                        "options": [
                          {
                            "name": "(Leave)",
                            "action": [
                              {
                                "setQuestFlag": {
                                  "key": "mainQuest",
                                  "val": 1
                                },
                                "activateMapObject": 78
                              }
                            ]
                          }
                        ]
                      }
                    ]
                  }
                ]
              }
            ]
          }
        ]
      },
      {
        "name": "Goodbye."
      }
    ]
  },
  {
    "condition": [
      {
        "checkQuestFlag": "Ch1CastlesComplete",
        "getQuestFlag": {
          "key": "Ch1CastlesComplete",
          "op": "<",
          "val": 5
        }
      }
    ],
    "text": "\"{var=player_name}! I feel the Guardians' spell growing weaker! Defeat them all and you may save us yet.\"",
    "options": [
      {
        "name": "\"Goodbye.\""
      }
    ]
  },
  {
    "condition": [
      {
        "getQuestFlag": {
          "key": "Ch1CastlesComplete",
          "op": ">=",
          "val": 5
        }
      }
    ],
    "text": "\"Orazca stands, and the five thrones are broken. Welcome home, {var=player_name}.\"",
    "options": [
      {
        "action": [
          {
            "removeItem": "",
            "setColorIdentity": "",
            "advanceQuestFlag": "",
            "advanceMapFlag": "",
            "setQuestFlag": {
              "key": "mainQuest",
              "val": 3
            },
            "setMapFlag": {
              "key": ""
            },
            "issueQuest": "",
            "POIReference": ""
          }
        ],
        "name": "\"The five castles have fallen. The Seals are mine again.\"",
        "text": "\"Then it is done - what was stolen is restored. But hear an old man's last warning: the Five did not invent your prison. They found its design.\"",
        "options": [
          {
            "name": "\"Found it... where?\"",
            "text": "\"Beneath this realm there are older doors, Guardian - older than my order, older than your wardenship. Your Seals were never only bindings. They were also locks.\"",
            "options": [
              {
                "name": "(Continue)",
                "text": "\"Now those locks sit in your pocket instead of on the doors - and whatever slept behind them has had three thousand years to grow hungry. Rest. Rebuild. And keep your deck close, Guardian.\"",
                "options": [
                  {
                    "name": "(Continue)",
                    "text": "[RED]Developer's note:[] You have reached the end of The Forsaken Realms' current story content - but the realm fights on: territory, research, restoration and the Five continue. Several difficult dungeons have also been added to your world map.",
                    "options": [
                      {
                        "name": "(Continue)",
                        "text": "[RED]Developer's note:[] Watch for the next release to continue the story - and thanks for coming on this Adventure with us!",
                        "options": [
                          {
                            "name": "(Chapter 1 complete)"
                          }
                        ]
                      }
                    ]
                  }
                ]
              }
            ]
          }
        ]
      }
    ]
  },
  {
    "condition": [
      {
        "item": "Blue Key"
      },
      {
        "item": "Green Key"
      },
      {
        "item": "Black Key"
      },
      {
        "item": "White Key"
      },
      {
        "item": "Red Key"
      }
    ],
    "text": "Hello again",
    "options": [
      {
        "name": "I want to trade in the five colored keys for a mox of my choice and the key to Emrakul's room",
        "action": [
          {
            "grantRewardsChoice": [
              {
                "type": "card",
                "count": 1,
                "cardName": "Mox Jet"
              },
              {
                "type": "card",
                "count": 1,
                "cardName": "Mox Ruby"
              },
              {
                "type": "card",
                "count": 1,
                "cardName": "Mox Sapphire"
              },
              {
                "type": "card",
                "count": 1,
                "cardName": "Mox Pearl"
              },
              {
                "type": "card",
                "count": 1,
                "cardName": "Mox Emerald"
              }
            ]
          },
          {
            "removeItem": "Blue Key"
          },
          {
            "removeItem": "Green Key"
          },
          {
            "removeItem": "Black Key"
          },
          {
            "removeItem": "White Key"
          },
          {
            "removeItem": "Red Key"
          },
          {
            "addItem": "Strange Key"
          }
        ]
      }
    ]
  }
]
